(function(){
  if (window.__specInstalled__) return;
  window.__specInstalled__ = true;
  var canvas = document.getElementById('specCanvas');
  var ctx = canvas.getContext('2d');
  var nhSlider = document.getElementById('nhSlider');
  var nhVal = document.getElementById('nhVal');
  var nlSlider = document.getElementById('nlSlider');
  var nlVal = document.getElementById('nlVal');
  var eSlider = document.getElementById('eSlider');
  var eVal = document.getElementById('eVal');
  var out = document.getElementById('specOut');
  var modeBtn = document.getElementById('modeBtn');
  var playBtn = document.getElementById('playBtn');
  var emitRows = document.getElementById('emitRows');
  var absRows = document.getElementById('absRows');
  var mode = 'emit';
  var running = false, pulse = 0;
  var E1 = 13.6;
  window.simState = { mode: 'emit', nHigh: 3, nLow: 2, dE: 0, lambda: 0, running: false };
  function En(n){ return -E1 / (n * n); }
  function wlColor(nm){
    var r, g, b;
    if (nm >= 380 && nm < 440) { r = -(nm - 440) / 60; g = 0; b = 1; }
    else if (nm >= 440 && nm < 490) { r = 0; g = (nm - 440) / 50; b = 1; }
    else if (nm >= 490 && nm < 510) { r = 0; g = 1; b = -(nm - 510) / 20; }
    else if (nm >= 510 && nm < 580) { r = (nm - 510) / 70; g = 1; b = 0; }
    else if (nm >= 580 && nm < 645) { r = 1; g = -(nm - 645) / 65; b = 0; }
    else if (nm >= 645 && nm <= 760) { r = 1; g = 0; b = 0; }
    else { r = 1; g = 1; b = 1; }
    return 'rgb(' + Math.round(r * 255) + ',' + Math.round(g * 255) + ',' + Math.round(b * 255) + ')';
  }
  function rainbow(x, y, w, h){
    var grad = ctx.createLinearGradient(x, 0, x + w, 0);
    grad.addColorStop(0, wlColor(380));
    grad.addColorStop(0.2, wlColor(450));
    grad.addColorStop(0.4, wlColor(500));
    grad.addColorStop(0.6, wlColor(560));
    grad.addColorStop(0.8, wlColor(640));
    grad.addColorStop(1, wlColor(760));
    ctx.fillStyle = grad;
    ctx.fillRect(x, y, w, h);
  }
  function nmToX(nm){ return 50 + ((nm - 380) / 380) * (canvas.width - 100); }
  function drawLevels(nHigh, nLow){
    var x0 = 60, w = 240;
    var topY = 40, bottomY = 300;
    var yOf = function(n){ return bottomY - ((E1 - E1 / (n * n)) / E1) * (bottomY - topY); };
    ctx.strokeStyle = '#64748b'; ctx.lineWidth = 1.5;
    for (var n = 1; n <= 6; n++) {
      var y = yOf(n);
      ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x0 + w, y); ctx.stroke();
      ctx.fillStyle = '#94a3b8'; ctx.font = '12px sans-serif';
      ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
      ctx.fillText('n=' + n + '  E=' + En(n).toFixed(2) + ' eV', x0 - 8, y);
    }
    var y1 = yOf(nLow), y2 = yOf(nHigh);
    ctx.strokeStyle = '#f59e0b'; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.moveTo(x0 + w / 2, y2); ctx.lineTo(x0 + w / 2, y1); ctx.stroke();
    ctx.fillStyle = '#f59e0b';
    ctx.beginPath();
    var tipY = mode === 'emit' ? y1 : y2;
    ctx.moveTo(x0 + w / 2, tipY);
    ctx.lineTo(x0 + w / 2 - 7, tipY + (mode === 'emit' ? -7 : 7));
    ctx.lineTo(x0 + w / 2 + 7, tipY + (mode === 'emit' ? -7 : 7));
    ctx.closePath(); ctx.fill();
    if (running) {
      var fromY = mode === 'emit' ? y2 : y1;
      var toY = mode === 'emit' ? y1 : y2;
      var py = fromY + (toY - fromY) * ((pulse % 1) + 1) % 1;
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(x0 + w / 2, py, 5, 0, Math.PI * 2); ctx.fill();
    }
  }
  function drawEmit(){
    var nh = parseInt(nhSlider.value), nl = parseInt(nlSlider.value);
    if (nl >= nh) { nl = nh - 1; nlSlider.value = nl; }
    var dE = E1 * (1 / (nl * nl) - 1 / (nh * nh));
    var lambda = 1240 / dE;
    drawLevels(nh, nl);
    var sy = 330, sh = 24;
    rainbow(50, sy, canvas.width - 100, sh);
    ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 2;
    ctx.strokeRect(50, sy, canvas.width - 100, sh);
    var inVis = lambda >= 380 && lambda <= 760;
    var lx = inVis ? nmToX(lambda) : (lambda < 380 ? 50 : canvas.width - 50);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(lx, sy - 6); ctx.lineTo(lx, sy + sh + 6); ctx.stroke();
    var colName = inVis ? (lambda < 490 ? 'بنفسجي/أزرق' : lambda < 570 ? 'أخضر' : lambda < 610 ? 'أصفر' : 'أحمر') : (lambda < 380 ? 'تحت البنفسجي UV' : 'تحت الأحمر IR');
    out.textContent = 'إصدار: ΔE = ' + dE.toFixed(2) + ' eV | λ = ' + lambda.toFixed(0) + ' nm (' + colName + ')';
    window.simState.nHigh = nh; window.simState.nLow = nl;
    window.simState.dE = dE; window.simState.lambda = lambda;
    nhVal.textContent = nh;
    nlVal.textContent = nl;
  }
  function drawAbsorb(){
    var E = parseFloat(eSlider.value);
    var nl = parseInt(nlSlider.value);
    var best = null, bestD = 1e9;
    for (var n = nl + 1; n <= 6; n++) {
      var dE = E1 * (1 / (nl * nl) - 1 / (n * n));
      if (Math.abs(dE - E) < bestD) { bestD = Math.abs(dE - E); best = n; }
    }
    var absorbed = bestD < 0.06 && best;
    var dE = absorbed ? E1 * (1 / (nl * nl) - 1 / (best * best)) : E;
    var lambda = 1240 / dE;
    if (absorbed) drawLevels(best, nl); else drawLevels(2, nl);
    var sy = 330, sh = 24;
    rainbow(50, sy, canvas.width - 100, sh);
    var wls = [410, 434, 486, 656];
    for (var i = 0; i < wls.length; i++) {
      ctx.strokeStyle = '#000'; ctx.lineWidth = 4;
      var dx = nmToX(wls[i]);
      ctx.beginPath(); ctx.moveTo(dx, sy - 4); ctx.lineTo(dx, sy + sh + 4); ctx.stroke();
    }
    ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 2;
    ctx.strokeRect(50, sy, canvas.width - 100, sh);
    if (absorbed) {
      ctx.fillStyle = '#fff'; ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'top';
      ctx.fillText('فوتون ممتص', nmToX(lambda), sy + sh + 8);
    }
    out.textContent = absorbed
      ? 'امتصاص: الفوتون (E=' + E.toFixed(2) + ' eV) ينقل الإلكترون من n=' + nl + ' إلى n=' + best + ' | λ = ' + lambda.toFixed(0) + ' nm'
      : 'لا امتصاص: طاقة الفوتون (' + E.toFixed(2) + ' eV) لا تطابق أي انتقال من n=' + nl;
    window.simState.dE = dE; window.simState.lambda = lambda;
    eVal.textContent = E.toFixed(1);
  }
  function draw(){
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#0b1020'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    if (mode === 'emit') drawEmit(); else drawAbsorb();
  }
  modeBtn.addEventListener('click', function(){
    mode = mode === 'emit' ? 'abs' : 'emit';
    window.simState.mode = mode;
    modeBtn.textContent = mode === 'emit' ? 'وضع الامتصاص' : 'وضع الإصدار';
    emitRows.style.display = mode === 'emit' ? 'flex' : 'none';
    absRows.style.display = mode === 'emit' ? 'none' : 'flex';
    out.textContent = '';
  });
  playBtn.addEventListener('click', function(){
    running = !running;
    window.simState.running = running;
    playBtn.textContent = running ? 'إيقاف' : 'تشغيل الانتقال';
  });
  nhSlider.addEventListener('input', function(){});
  nlSlider.addEventListener('input', function(){});
  eSlider.addEventListener('input', function(){});
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){ if (running) pulse += 0.02; draw(); requestAnimationFrame(loop); }
  loop();
})();
